name: AI Docs Review Slash Command

on:
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'Pull Request number to review'
        required: true
        type: string

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  ai_docs_review:
    runs-on: ubuntu-latest
    steps:
      - name: Generate Octavia Bot token
        id: octavia_token
        uses: actions/github-script@v6
        with:
          script: |
            const jwt = require('jsonwebtoken');
            const appId = process.env.OCTAVIA_BOT_APP_ID;
            const privateKey = process.env.OCTAVIA_BOT_PRIVATE_KEY.replace(/\\n/g, '\n');
            const now = Math.floor(Date.now() / 1000);
            const payload = { iat: now - 60, exp: now + (10 * 60), iss: appId };
            const jwtToken = jwt.sign(payload, privateKey, { algorithm: 'RS256' });
            const { data: installation } = await github.apps.getInstallationForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            const { data: token } = await github.apps.createInstallationAccessToken({
              installation_id: installation.id
            });
            core.setOutput('token', token.token);
        env:
          OCTAVIA_BOT_APP_ID: ${{ secrets.OCTAVIA_BOT_APP_ID }}
          OCTAVIA_BOT_PRIVATE_KEY: ${{ secrets.OCTAVIA_BOT_PRIVATE_KEY }}

      - name: Validate PR number
        if: ${{ inputs.pr_number == '' }}
        run: |
          echo "Error: PR number is required."
          exit 1

      - name: Get changed files
        id: changed_files
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = parseInt(process.env.PR_NUMBER, 10);
            const { data: files } = await github.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
              per_page: 100
            });
            const connectorRegex = /^airbyte-integrations\/connectors\/[^/]+\/.*/;
            const hasConnector = files.some(f => connectorRegex.test(f.filename));
            core.setOutput('has_connector', hasConnector);
            core.setOutput('files', JSON.stringify(files.map(f => f.filename)));
        env:
          PR_NUMBER: ${{ inputs.pr_number }}
          GITHUB_TOKEN: ${{ steps.octavia_token.outputs.token }}

      - name: Post started comment
        id: comment_started
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            :hourglass_flowing_sand: **AI Docs Review** started...
          pr-number: ${{ inputs.pr_number }}
          github-token: ${{ steps.octavia_token.outputs.token }}
          comment-tag: ai-docs-review
          mode: replace
        if: ${{ steps.changed_files.outputs.has_connector == 'true' }}

      - name: Post skipped comment
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            :white_check_mark: **AI Docs Review** skipped – no connector changes detected.
          pr-number: ${{ inputs.pr_number }}
          github-token: ${{ steps.octavia_token.outputs.token }}
          comment-tag: ai-docs-review
          mode: replace
        if: ${{ steps.changed_files.outputs.has_connector == 'false' }}

      - name: Trigger Devin AI review
        uses: aaronsteers/devin-action@main
        with:
          comment-id: ${{ steps.comment_started.outputs.comment-id }}
          issue-number: ${{ inputs.pr_number }}
          playbook-macro: !connectordocs_pr_review
          devin-token: ${{ secrets.DEVIN_TOKEN }}
          github-token: ${{ steps.octavia_token.outputs.token }}
          start-message: |
            :robot: Running AI Docs Review...
          tags: ai-docs-review
        if: ${{ steps.changed_files.outputs.has_connector == 'true' }}

      - name: Post error comment
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            :x: **AI Docs Review** failed due to an error.
          pr-number: ${{ inputs.pr_number }}
          github-token: ${{ steps.octavia_token.outputs.token }}
          comment-tag: ai-docs-review
          mode: replace
        if: failure()
